    ∧ ¬ Bet_Point (Se C2 C1) B1 ∧ Def (Ang (An A2 B1 C2))" by blast
  from assms have "Def (Tri (Tr A B C))" by (simp add:Ang_to_Tri)
  then have P3 : "Def (Tri (Tr B A C))" by (blast intro:Tri_def_rev Tri_def_trans)
