Theorem (Congruence of Angles in Incidence Geometry):
Given a plane with points x, y, z1, and z2, and lines Li, Se, and Poi, if the following conditions hold:
1. The difference in slopes between Li and Poi at x is not equal to the difference at y.
2. The line segments Se(x, z1) and Se(x, z2) are equal.
3. The line segments Se(y, z1) and Se(y, z2) are equal.
4. There exists a point p such that it lies on Li, is collinear with x and y, and the slopes of Poi at x and Poi at p are equal.

Then the angles formed by the intersection of Li with Se(x, z1) and Se(x, z2) are congruent, as are the angles formed by the intersection of Li with Se(y, z1) and Se(y, z2).

lemma (in Congruence_Rule) Tri_week_SSS_lemma1 :
  assumes
    "Plane_diffside (Li x y) z1 z2"
    "¬ Eq (Geos (Poi x) add Emp) (Geos (Poi y) add Emp)"
    "Eq (Geos (Seg (Se x z1)) add Emp) (Geos (Seg (Se x z2)) add Emp)"
    "Eq (Geos (Seg (Se y z1)) add Emp) (Geos (Seg (Se y z2)) add Emp)"
    "∃p. Bet_Point (Se z1 z2) p ∧ Line_on (Li x y) p ∧ Eq (Geos (Poi x) add Emp) (Geos (Poi p) add Emp)"
  shows "Cong (Geos (Ang (An x z1 y)) add Emp) (Geos (Ang (An x z2 y)) add Emp)"
proof -
  from assms have P1 : "∃p. Bet_Point (Se z1 z2) p ∧ Line_on (Li x y) p 
    ∧ ¬ Line_on (Li x y) z1 ∧ ¬ Line_on (Li x y) z2" by (simp add:Plane_diffside_def)
  from assms obtain pn :: Point where P2 : "Bet_Point (Se z1 z2) pn ∧ Line_on (Li x y) pn ∧ Eq (Geos (Poi x) add Emp) (Geos (Poi pn) add Emp)" by blast
  from P2 have P3 : "Bet_Point (Se z1 z2) pn" by simp
  then have P4 : "Line_on (Li z1 z2) pn" by (simp add:Line_Bet_on)
  from P2 P4 have P5 : "Line_on (Li z1 z2) x" by (blast intro:Eq_rev Point_Eq)
  from assms P3 have P6 : "Bet_Point (Se z1 z2) x" by (blast intro:Eq_rev Point_Eq)
  have P7 : "Line_on (Li x y) x" by (simp add:Line_on_rule)
  have P8 : "Line_on (Li x y) y" by (simp add:Line_on_rule)
  from assms P5 P7 P8 have P9 : "Line_on (Li z1 z2) y ⟹ Eq (Geos (Lin (Li z1 z2)) add Emp) (Geos (Lin (Li x y)) add Emp)" by (simp add:Line_unique)
  have P10 : "Line_on (Li z1 z2) z1" by (simp add:Line_on_rule)
  from P9 P10 have P11 : "Line_on (Li z1 z2) y ⟹ Line_on (Li x y) z1" by (simp add:Line_on_trans)
  from P1 P11 have P12 : "¬ Line_on (Li z1 z2) y" by blast
  from P3 have P13 : "¬ Eq (Geos (Poi z1) add Emp) (Geos (Poi z2) add Emp)" by (simp add:Bet_Point_def)
  from P8 have P14 : "Eq (Geos (Poi z2) add Emp) (Geos (Poi y) add Emp) ⟹ Line_on (Li x y) z2" by (blast intro:Eq_rev Point_Eq)
  from P1 P14 have P15 : "¬ Eq (Geos (Poi z2) add Emp) (Geos (Poi y) add Emp)" by blast
  from P8 have P16 : "Eq (Geos (Poi y) add Emp) (Geos (Poi z1) add Emp) ⟹ Line_on (Li x y) z1" by (blast intro:Eq_rev Point_Eq)
  from P1 P16 have P17 : "¬ Eq (Geos (Poi y) add Emp) (Geos (Poi z1) add Emp)" by blast
  from P12 P13 have P18 : "Def (Tri (Tr z1 z2 y))" by (simp add:Ang_sinple_def Ang_to_Tri)
  then have P19 : "Def (Tri (Tr y z1 z2))" by (blast intro:Tri_def_trans)
  from assms P19 have P20 : "Cong (Geos (Ang (An y z1 z2)) add Emp) (Geos (Ang (An y z2 z1)) add Emp)" by (simp add:Tri_isosceles)
  from P18 have P21 : "Def (Ang (An z1 z2 y))" by (simp add:Tri_to_Ang)
  from P6 have P22 : "Line_on (Li z2 z1) x" by (simp add:Line_Bet_on)
  from P6 have P23 : "Inv (Bet_Point (Se z2 x) z1) ∧ Inv (Bet_Point (Se x z1) z2)" by (simp add:Bet_iff)
  then have "¬ Bet_Point (Se x z1) z2" by (simp add:Inv_def)
  then have P24 : "¬ Bet_Point (Se z1 x) z2" by (blast intro:Bet_rev)
  have P25 : "Line_on (Li z2 y) y" by (simp add:Line_on_rule)
  have P26 : "¬ Bet_Point (Se y y) z2" by (simp add:Bet_end_Point)
  from P6 have P27 : "¬ Eq (Geos (Poi z2) add Emp) (Geos (Poi x) add Emp)" by (simp add:Bet_Point_def)
  from P15 P21 P22 P24 P25 P26 P27 have P28 : 
    "Eq (Geos (Ang (An z1 z2 y)) add Emp) (Geos (Ang (An x z2 y)) add Emp) ∧ Def (Ang (An x z2 y))" by (simp add:Ang_Point_swap)
  have P29 : "Eq (Geos (Ang (An y z2 z1)) add Emp) (Geos (Ang (An z1 z2 y)) add Emp)" by (simp add:Ang_roll)
  from P20 P29 have P30 : "Cong (Geos (Ang (An y z1 z2)) add Emp) (Geos (Ang (An z1 z2 y)) add Emp)" by (blast intro:Ang_weektrans Ang_rev Eq_rev)
  from P28 P30 have P31 : "Cong (Geos (Ang (An y z1 z2)) add Emp) (Geos (Ang (An x z2 y)) add Emp)" by (blast intro:Ang_weektrans Ang_rev Eq_rev)
  from P19 have P32 : "Def (Ang (An z2 z1 y))" by (blast intro:Tri_to_Ang Tri_def_rev)
  from P6 have P33 : "Line_on (Li z1 z2) x" by (simp add:Line_Bet_on)
  from P23 have P34 : "¬ Bet_Point (Se z2 x) z1" by (simp add:Inv_def)
  have P35 : "Line_on (Li z1 y) y" by (simp add:Line_on_rule)
  have P36 : "¬ Bet_Point (Se y y) z1" by (simp add:Bet_end_Point)
  from P6 have "¬ Eq (Geos (Poi x) add Emp) (Geos (Poi z1) add Emp)" by (simp add:Bet_Point_def)
  then have P37 : "¬ Eq (Geos (Poi z1) add Emp) (Geos (Poi x) add Emp)" by (blast intro:Eq_rev)
  from P17 have P38 : "¬ Eq (Geos (Poi z1) add Emp) (Geos (Poi y) add Emp)" by (blast intro:Eq_rev)
  from P32 P33 P34 P35 P36 P37 P38 have P39 : 
    "Eq (Geos (Ang (An z2 z1 y)) add Emp) (Geos (Ang (An x z1 y)) add Emp) ∧ Def (Ang (An x z1 y))" by (simp add:Ang_Point_swap)
  have P40 : "Eq (Geos (Ang (An y z1 z2)) add Emp) (Geos (Ang (An z2 z1 y)) add Emp)" by (simp add:Ang_roll)
  from P31 P40 have P41 : "Cong (Geos (Ang (An z2 z1 y)) add Emp) (Geos (Ang (An x z2 y)) add Emp)" by (blast intro:Ang_weektrans Ang_rev Eq_rev)
